Fix errors in this Unity test code.

Unit Test Code:
#include "unity.h"
#include "buffer.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_buffer_slice_negative_to_relative_to_end(void) {
    // Setup: create a buffer with known data
    buffer_t *src = helper_make_buffer_with_data("abcdefg");
    // buffer length = 7

    // Choose from = 2, to = -3
    // According to the implementation:
    // to < 0 --> to = len - ~to
    // ~to = ~(-3) = 2, so to = 7 - 2 = 5
    // So, slice from index 2 (inclusive) to 5 (exclusive): "cde"
    size_t from = 2;
    ssize_t to = -3;

    buffer_t *slice = buffer_slice(src, from, to);

    // Assertions
    TEST_ASSERT_NOT_NULL(slice);
    helper_assert_buffer_length(slice, 3);
    helper_assert_buffer_data_equals(slice, "cde");

    // Cleanup
    buffer_free(src);
    buffer_free(slice);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_buffer_slice_negative_to_relative_to_end);
    return UNITY_END();
}

