    if (buf && str) {
        size_t copy_len = strlen(str);
        if (copy_len >= size) copy_len = size - 1;
        memcpy(buf->data, str, copy_len);
        buf->data[copy_len] = '\0';
        buf->length = copy_len; // FIX: update buffer's length field
    } else if (buf) {
        buf->data[0] = '\0';
        buf->length = 0; // Also set length to 0 if no data
    }
    return buf;
}


